"""Read-only versioned-store completeness and team/map/mode/era coverage."""
import argparse,json
from pathlib import Path
import pandas as pd
ap=argparse.ArgumentParser();ap.add_argument('--store',type=Path,required=True);ap.add_argument('--out',type=Path,required=True);a=ap.parse_args();g=pd.read_parquet(a.store/'games.parquet');d=pd.concat([pd.read_parquet(p) for p in (a.store/'sides').glob('*.parquet')]);g.game=g.game.astype(str);d.game=d.game.astype(str);assert not d.duplicated(['game','side']).any();x=d.merge(g[['game','ranked','era','started_at','series_id']],on='game',validate='many_to_one');b=json.loads((a.store/'last-build.json').read_text());v={'games':int(d.game.nunique()),'sides':len(d),'metadata_games':len(g),'by_mode_games':{str(k):int(v) for k,v in g[g.game.isin(d.game)].groupby('ranked').size().items()},'by_era_games':g[g.game.isin(d.game)].groupby('era').size().to_dict(),'pending_from_last_selection':len(set(b['selected_game_ids'])-set(d.game)),'team_map_mode':[dict(team=str(t),map=m,ranked=bool(r),sides=len(z),series=int(z.series_id.nunique())) for (t,m,r),z in x.groupby(['team','map','ranked'])]};a.out.write_text(json.dumps(v,indent=2,default=int)+'\n');print({k:v for k,v in v.items() if k!='team_map_mode'})
